<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { downloadReport, loadReport, loadTrend, downloadTrend, type TrendResult, type TrendQuery, loadReportAccess, monthWindow, type Cell, type ReportAccess, type ReportMode, type ReportResult } from './api'
const previous=new Date();previous.setUTCDate(1);previous.setUTCMonth(previous.getUTCMonth()-1)
const route=useRoute()
const month=ref((route.meta.permission==='reports:aggregate'?previous:new Date()).toISOString().slice(0,7)),mode=ref<ReportMode>(route.meta.permission==='reports:aggregate'?'board':'operational'),zone=ref(''),department=ref(''),caseType=ref('')
const access=ref<ReportAccess>({permissions:[],grants:[]}),result=ref<ReportResult|null>(null),busy=ref(false),error=ref(''),notice=ref('')
const trend=ref<TrendResult|null>(null),trendMonths=ref(6),trendDimension=ref<TrendQuery['dimension']>('zone')
const trendMax=computed(()=>Math.max(1,...(trend.value?.periods.map(p=>p.new_cases)??[])))
function trendQuery():TrendQuery{return {end_month:month.value,months:trendMonths.value,dimension:trendDimension.value,zone:zone.value,department:department.value,case_type:caseType.value}}
let disposed=false,generation=0
const allowedModes=computed(()=>[{id:'operational' as ReportMode,label:'Operational cases',permission:'reports:operational'},{id:'board' as ReportMode,label:'Leadership summary',permission:'reports:aggregate'}].filter(m=>access.value.permissions.includes(m.permission)))
const canExport=computed(()=>access.value.permissions.includes('reports:export'))
const tables=computed(()=>result.value?[{title:'Zone at intake',cells:cells(result.value.report.by_zone)},{title:'Department at intake',cells:cells(result.value.report.by_department)},{title:'Case type at intake',cells:cells(result.value.report.by_case_type)}]:[])
function utcStamp(value:string){const date=new Date(value);return Number.isFinite(date.getTime())?date.toISOString().slice(0,19).replace('T',' ')+' UTC':'Unavailable'}
function cells(value:Record<string,number>|Cell[]):Cell[]{return Array.isArray(value)?value:Object.entries(value).sort(([a],[b])=>a.localeCompare(b)).map(([label,value])=>({label,value,suppressed:false}))}
function query(){return {...monthWindow(month.value),...(mode.value==='operational'?{zone:zone.value,department:department.value,case_type:caseType.value}:{})}}
function failure(e:unknown){const status=(e as {response?:{status?:number}}).response?.status;return status===403?'Your session or current report access changed. Reverify and refresh.':status===409?'The source changed while this report was being prepared. Refresh to use the current scope.':status===400?'Choose a valid period. Leadership summaries require a completed calendar month.':'Reporting is unavailable. Check the configured source and disclosure policy.'}
async function refresh(){if(busy.value)return;const token=++generation;busy.value=true;result.value=null;trend.value=null;error.value='';notice.value='';try{const current=await loadReportAccess();if(disposed||token!==generation)return;access.value=current;if(!allowedModes.value.some(m=>m.id===mode.value))mode.value=allowedModes.value[0]?.id??'operational';if(!allowedModes.value.length){error.value='Your current session has no report access.';return};const report=await loadReport(mode.value,query());const series=mode.value==='operational'?await loadTrend(trendQuery()):null;if(!disposed&&token===generation){result.value=report;trend.value=series}}catch(e){if(!disposed&&token===generation){result.value=null;trend.value=null;error.value=failure(e)}}finally{if(!disposed&&token===generation)busy.value=false}}
async function exportCSV(){if(busy.value||!result.value)return;busy.value=true;error.value='';notice.value='';try{const blob=await downloadReport(mode.value,query());if(disposed)return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`case-report-${mode.value}-${month.value}.csv`;link.click();URL.revokeObjectURL(url);notice.value='Controlled CSV export downloaded.'}catch(e){result.value=null;trend.value=null;error.value=failure(e)}finally{if(!disposed)busy.value=false}}
async function exportTrend(){if(busy.value||!trend.value)return;busy.value=true;error.value='';try{const blob=await downloadTrend(trendQuery());if(disposed)return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`case-trend-${month.value}.csv`;link.click();URL.revokeObjectURL(url);notice.value='Controlled trend CSV downloaded.'}catch(e){result.value=null;trend.value=null;error.value=failure(e)}finally{if(!disposed)busy.value=false}}
function changed(){generation++;result.value=null;trend.value=null;error.value='';notice.value=''}
onMounted(refresh);onBeforeUnmount(()=>{disposed=true;generation++;result.value=null;trend.value=null;access.value={permissions:[],grants:[]}})
</script>
<template>
 <main class="reports-page"><header><div><h1>Case reporting</h1><p>Historical lifecycle facts with current case access and creation-time dimensions.</p></div><button :disabled="busy" @click="refresh">Refresh report</button></header>
  <form class="filters" @submit.prevent="refresh"><label>View<select v-model="mode" :disabled="busy" @change="changed"><option v-for="option in allowedModes" :key="option.id" :value="option.id">{{ option.label }}</option></select></label><label>Calendar month (UTC)<input v-model="month" type="month" :disabled="busy" required @change="changed" /></label><template v-if="mode==='operational'"><label>Trend months<select v-model.number="trendMonths" :disabled="busy" @change="changed"><option :value="3">3 months</option><option :value="6">6 months</option><option :value="12">12 months</option></select></label><label>Trend dimension<select v-model="trendDimension" :disabled="busy" @change="changed"><option value="zone">Zone</option><option value="department">Department</option><option value="case_type">Case type</option></select></label><label>Zone<input v-model="zone" :disabled="busy" placeholder="All authorized zones" @input="changed" /></label><label>Department<input v-model="department" :disabled="busy" placeholder="All authorized departments" @input="changed" /></label><label>Case type<input v-model="caseType" :disabled="busy" placeholder="All authorized types" @input="changed" /></label></template><button :disabled="busy">Apply</button></form>
  <p v-if="mode==='board'" class="guidance">Leadership summaries use completed calendar months. Custom cohort filters are disabled. Small groups suppress all related totals and tables.</p><p v-if="busy" role="status">Preparing your authorized report...</p><p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
  <template v-if="result"><p class="scope">{{ result.metadata.scope }} - As of {{ utcStamp(result.metadata.as_of) }}</p><p v-if="result.report.partial" class="guidance">Partial period: activity after the snapshot is excluded.</p><p v-if="result.report.suppressed" class="guidance" role="status">Disclosure controls suppressed this summary. A blank value means suppressed, not zero.</p>
   <section class="metrics" aria-label="Case metrics"><article><h2>New submitted cases</h2><strong>{{ result.report.new_cases ?? 'Suppressed' }}</strong></article><article><h2>Resolved from this cohort</h2><strong>{{ result.report.resolved_created_in_period ?? 'Suppressed' }}</strong></article><article><h2>Backlog at snapshot</h2><strong>{{ result.report.backlog ?? 'Suppressed' }}</strong></article></section>
   <section class="tables"><article v-for="table in tables" :key="table.title"><h2>{{ table.title }}</h2><table><thead><tr><th scope="col">Group</th><th scope="col">New cases</th></tr></thead><tbody><tr v-for="cell in table.cells" :key="cell.label"><th scope="row">{{ cell.label || 'Unspecified' }}</th><td>{{ cell.suppressed ? 'Suppressed' : cell.value }}</td></tr><tr v-if="!table.cells.length"><td colspan="2">No authorized cases in this cohort.</td></tr></tbody></table></article></section>
   <section v-if="trend" class="trend" aria-label="Historical case trends"><h2>Case trends by {{trend.dimension.replace('_',' ')}}</h2><p>Actual submitted cases by month; dimensions remain as recorded at intake. Current authorization applies to every period.</p><figure><figcaption>New submitted cases per UTC month</figcaption><svg viewBox="0 0 640 220" role="img" aria-label="New submitted cases by month"><title>Monthly case trend; exact counts and groups follow in the table</title><g v-for="(period,index) in trend.periods" :key="period.month"><rect :x="35+index*570/trend.periods.length" :y="175-period.new_cases*140/trendMax" :width="Math.max(8,570/trend.periods.length-15)" :height="period.new_cases*140/trendMax" fill="currentColor"/><text :x="35+index*570/trend.periods.length" :y="165-period.new_cases*140/trendMax" fill="currentColor" font-size="12">{{period.new_cases}}</text><text :x="35+index*570/trend.periods.length" y="200" fill="currentColor" font-size="11">{{period.month}}</text></g></svg></figure><div class="trend-table"><table><caption>Historical monthly totals and {{trend.dimension.replace('_',' ')}} cohorts</caption><thead><tr><th scope="col">UTC month</th><th scope="col">New</th><th scope="col">Resolved from cohort</th><th scope="col">Backlog at period end</th><th scope="col">New cases by group</th></tr></thead><tbody><tr v-for="period in trend.periods" :key="period.month"><th scope="row">{{period.month}}<small v-if="period.partial"> · Partial</small></th><td>{{period.new_cases}}</td><td>{{period.resolved_created_in_period}}</td><td>{{period.backlog}}</td><td><ul v-if="period.groups.length"><li v-for="cell in period.groups" :key="cell.label">{{cell.label || 'Unspecified'}}: {{cell.value}}</li></ul><span v-else>No new cases</span></td></tr></tbody></table></div><button v-if="canExport" :disabled="busy" @click="exportTrend">Download controlled trend CSV</button><p class="footnote">{{trend.scope}} · Snapshot {{utcStamp(trend.as_of)}}. Message volumes are not inferred from cases.</p></section>
   <section class="service"><h2>Service volumes</h2><p v-if="!result.metadata.service_metrics.available">Unavailable: {{ result.metadata.service_metrics.reason }}. No service volume is inferred from case counts.</p><p v-else>Messages: {{ result.report.messages ?? 'Suppressed' }} - Enquiries: {{ result.report.enquiries ?? 'Suppressed' }}</p></section><button v-if="canExport" :disabled="busy" @click="exportCSV">Download controlled CSV</button><p class="footnote">Exports apply current access and disclosure rules again. Counts include currently accessible cases; they do not grant access to case narratives.</p>
  </template>
 </main>
</template>
<style scoped>
.reports-page{max-width:1350px;margin:auto;padding:2rem;color:hsl(var(--foreground))}header{display:flex;justify-content:space-between;gap:1rem;align-items:center;margin-bottom:1.5rem}h1{font-size:1.7rem;font-weight:650}h2{font-size:1rem;font-weight:600;margin-bottom:.6rem}p{margin:.6rem 0}.filters{display:flex;align-items:end;gap:.8rem;flex-wrap:wrap;padding:1rem;border:1px solid hsl(var(--border));border-radius:.6rem}label{display:grid;gap:.35rem;font-size:.9rem}input,select,button{border:1px solid hsl(var(--border));border-radius:.35rem;padding:.6rem;background:hsl(var(--background))}button{cursor:pointer;background:hsl(var(--secondary))}button:disabled{opacity:.5;cursor:default}.metrics,.tables{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;margin:1rem 0}article,.service{border:1px solid hsl(var(--border));border-radius:.6rem;background:hsl(var(--card));padding:1.1rem}.metrics strong{font-size:2rem}.guidance{padding:.8rem;background:hsl(var(--muted));border-radius:.35rem}.scope,.footnote{font-size:.85rem;color:hsl(var(--muted-foreground))}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:.6rem .3rem;border-bottom:1px solid hsl(var(--border));overflow-wrap:anywhere}thead{font-size:.8rem}tbody th{font-weight:400}.service{margin-bottom:1rem}.trend{border:1px solid hsl(var(--border));border-radius:.6rem;padding:1.1rem;margin:1rem 0}.trend svg{width:100%;max-height:260px;color:hsl(var(--primary))}.trend-table{overflow-x:auto;margin-bottom:1rem}figcaption,caption{text-align:left;font-size:.9rem;margin-bottom:.5rem}.error{color:#b42318}@media(max-width:800px){.reports-page{padding:1rem}.metrics,.tables{grid-template-columns:1fr}header{align-items:start}}
</style>
